// Residual-correction layer (2026-11-20): a tiny per-sex, per-field linear model
// `real - app = b0 + a*app + h*heightCm + w*weightKg + bmi*BMI + side*sideDepthUsed`
// applied AFTER fuseWithPrior to bust/waist/hip. Pure — no deps.
// Coefficients are generated by scripts/residual-fit/fit.ts (see reports/residual-fit.md);
// a missing sex/field entry = no correction. Corrections are clamped to +-MAX_CORRECTION_CM
// and skipped for fields in `est.outliers` (real-but-unusual bodies keep the raw scan).
// ANTHRO-FIT: tape re-tune pending (synth / BodyM disagree on waist).

import type { EstimatedMeasurements } from '../../types/measurements';
import type { Sex } from './landmarksToMeasurements';

export type ResidualField = 'body_bust' | 'body_waist' | 'body_hip';
export interface ResidualCoeff { b0: number; app: number; h: number; w: number; bmi: number; side: number }
export type ResidualCoeffs = Partial<Record<Sex, Partial<Record<ResidualField, ResidualCoeff>>>>;

export const MAX_CORRECTION_CM = 6;

// Generated by scripts/residual-fit/fit.ts on 2026-11-20; hip is BodyM-only (synth hip GT invalid) (units: cm, kg; original, not standardised).
export const RESIDUAL_COEFFS: ResidualCoeffs = {
  male: {
    body_bust: { b0: 94.03531, app: -0.69324, h: -0.29837, w: 0.67012, bmi: -0.86368, side: 0.06407 },
    body_waist: { b0: 20.31799, app: -0.72025, h: -0.01544, w: 0.31569, bmi: 0.99723, side: -1.43146 },
    body_hip: { b0: 18.97166, app: -0.28885, h: -0.00309, w: 0.08285, bmi: 0.21476, side: 0 },
  },
  female: {
    body_bust: { b0: 56.90927, app: -0.64072, h: -0.16643, w: 0.64598, bmi: -0.52623, side: 2.07037 },
    body_waist: { b0: -7.42807, app: -0.65968, h: 0.1328, w: 0.38871, bmi: 0.51851, side: 2.80693 },
    body_hip: { b0: 49.27209, app: -0.29947, h: -0.18878, w: 0.41308, bmi: -0.61515, side: 0 },
  },
};

const KEY = { body_bust: 'bust', body_waist: 'waist', body_hip: 'hip' } as const;
const FIELDS = Object.keys(KEY) as ResidualField[];

export function applyResidualCorrection(
  est: EstimatedMeasurements,
  inp: { sex?: Sex; heightCm?: number; weightKg?: number },
  coeffs: ResidualCoeffs = RESIDUAL_COEFFS,
): EstimatedMeasurements {
  const { sex, heightCm, weightKg } = inp;
  if (!sex || !heightCm || !weightKg || heightCm <= 0 || weightKg <= 0) return est;
  const bmi = weightKg / (heightCm / 100) ** 2;
  const out: EstimatedMeasurements = { ...est };
  for (const f of FIELDS) {
    const v = est[f], c = coeffs[sex]?.[f];
    if (v == null || !c || est.outliers?.includes(f)) continue;
    const side = est.depthSource?.[KEY[f]] === 'side' ? 1 : 0;
    const d = c.b0 + c.app * v + c.h * heightCm + c.w * weightKg + c.bmi * bmi + c.side * side;
    out[f] = Math.round(v + Math.max(-MAX_CORRECTION_CM, Math.min(MAX_CORRECTION_CM, d)));
  }
  return out;
}
